package test;

import org.eclipse.jface.preference.PreferenceDialog;
import org.eclipse.swt.widgets.Shell;
import org.eclipse.ui.dialogs.PreferencesUtil;

public class TestClass {
    public void configure(Shell shell) {
        // This is the pattern we want to match
        PreferencesUtil.createPreferenceDialogOn(shell, "org.eclipse.ui.preferencePages.ColorsAndFonts", null, null);

        // Another variant (different page ID)
        PreferenceDialog dialog = PreferencesUtil.createPreferenceDialogOn(shell, "org.eclipse.ui.preferencePages.General", new String[]{"someId"}, null);
        if (dialog != null) {
            dialog.open();
        }
    }
}

