package test;

import org.eclipse.jface.preference.PreferenceDialog;
import org.eclipse.swt.widgets.Shell;
import org.eclipse.ui.dialogs.PreferencesUtil;

public class TestClass {
    public void configure(Shell shell) {
        // This should NOT match (already correct string)
        PreferencesUtil.createPreferenceDialogOn(shell, "org.eclipse.ui.preferencePages.ColorsAndFonts", null, "selectCategory:org.eclipse.ui.workbenchMisc");

        // This should NOT match (different page ID)
        PreferencesUtil.createPreferenceDialogOn(shell, "org.eclipse.ui.preferencePages.General", null, null);

        // This should NOT match (different last argument type/value)
        PreferencesUtil.createPreferenceDialogOn(shell, "org.eclipse.ui.preferencePages.ColorsAndFonts", null, "someOtherString");

        // This should NOT match (different page ID and already correct)
        PreferenceDialog dialog = PreferencesUtil.createPreferenceDialogOn(shell, "org.eclipse.ui.preferencePages.General", new String[]{"someId"}, "selectCategory:org.eclipse.ui.workbenchMisc");
        if (dialog != null) {
            dialog.open();
        }
    }
}
